package reqs

import "testing"

// TestCompletionFocusParts checks a focus's own requirements, which only the
// Specialist's text states (ASSPE2270): each is and(program{focus}, its line
// read with the item grammar).
func TestCompletionFocusParts(t *testing.T) {
	runComplRuleCases(t, []complRuleCase{
		{"a focus's line is its requirement beside its program node; short of the amount, a pool of its courses (ASSPE2270, shortened)",
			"(1.0 credit plus a disciplinary focus requiring 2.0-3.5 credits)\n1. STA130H1, STA238H1\n**Disciplinary Focuses**\nStudents in the Specialist Program in Statistical Science: Methods and Practice program must enrol in and complete at least one disciplinary focus.\nHealth Studies (ASFOC2270A): (2.0 credits) HMB342H1, at least 0.5 credit from HST209H1/ PHS209H1/ HST211H1/ PHS211H1/ HST250H1/ PHS250H1, and at least 0.5 credit from HST308H1/ PHS308H1/ HST310H1/ PHS310H1/ HST405H1/ PHS405H1/ HST330H1/ PHS330H1/ HST440H1/ PHS440H1/ HST464H1/ PHS464H1\nSocial Psychology (ASFOC2270F): (2.0 credits) PSY100H1, PSY220H1, at least 1.0 from PSY320H1/ PSY321H1/ PSY322H1, PSY324H1/ PSY326H1/ PSY421H1/ PSY424H1/ PSY425H/ PSY426H1/ PSY427H1/ PSY405H1/ PSY406H1/ PSY405Y1/ PSY406Y1\nEcology (ASFOC2270L): (3.0 credits) BIO120H1, BIO220H1; 2.0 credits from (with at least a 0.5 credit at the 400-level) EEB319H1/ EEB321H1/ EEB328H1/ EEB365H1/ EEB428H1/ EEB440H1 or EEB240H1/ ENV432H1\nImmunology (3.0 Credits) - BIO130H1 (70%), IMM250H1, IMM340H1, IMM350H1, IMM360H1, IMM429H1/ IMM430H1/ IMM431H1/ IMM435H1",
			[]string{
				`1 allocation {"type":"credits","amount":1}`,
				`2 allocation p1 {"type":"and","items":[{"type":"course","code":"STA130H1"},{"type":"course","code":"STA238H1"}]}`,
				`3 allocation p1 {"type":"or","items":[{"type":"and","items":[{"type":"program","programs":["ASFOC2270A"],"text":"Health Studies"},{"type":"credits","amount":2,"courses":["HMB342H1","HST209H1","PHS209H1","HST211H1","PHS211H1","HST250H1","PHS250H1","HST308H1","PHS308H1","HST310H1","PHS310H1","HST405H1","PHS405H1","HST330H1","PHS330H1","HST440H1","PHS440H1","HST464H1","PHS464H1"]},{"type":"course","code":"HMB342H1"},{"type":"credits","amount":0.5,"courses":["HST209H1","PHS209H1","HST211H1","PHS211H1","HST250H1","PHS250H1"]},{"type":"credits","amount":0.5,"courses":["HST308H1","PHS308H1","HST310H1","PHS310H1","HST405H1","PHS405H1","HST330H1","PHS330H1","HST440H1","PHS440H1","HST464H1","PHS464H1"]}]},{"type":"and","items":[{"type":"program","programs":["ASFOC2270F"],"text":"Social Psychology"},{"type":"course","code":"PSY100H1"},{"type":"course","code":"PSY220H1"},{"type":"or","items":[{"type":"and","items":[{"type":"credits","amount":1,"courses":["PSY320H1","PSY321H1","PSY322H1","PSY324H1","PSY326H1","PSY421H1","PSY424H1","PSY425H1","PSY426H1","PSY427H1","PSY405H1","PSY406H1","PSY405Y1","PSY406Y1"]},{"type":"credits","amount":0.5,"courses":["PSY324H1","PSY326H1","PSY421H1","PSY424H1","PSY425H1","PSY426H1","PSY427H1","PSY405H1","PSY406H1","PSY405Y1","PSY406Y1"]}]},{"type":"and","items":[{"type":"credits","amount":1,"courses":["PSY320H1","PSY321H1","PSY322H1","PSY324H1","PSY326H1","PSY421H1","PSY424H1","PSY425H1","PSY426H1","PSY427H1","PSY405H1","PSY406H1","PSY405Y1","PSY406Y1"]},{"type":"text","kind":"ambiguity","text":"the \"/\" in PSY320H1/ PSY321H1/ PSY322H1 may separate the pool's courses rather than join alternatives, so more than one of them may count"}]}]}]},{"type":"and","items":[{"type":"program","programs":["ASFOC2270L"],"text":"Ecology"},{"type":"course","code":"BIO120H1"},{"type":"course","code":"BIO220H1"},{"type":"credits","amount":2,"courses":["EEB319H1","EEB321H1","EEB328H1","EEB365H1","EEB428H1","EEB440H1","EEB240H1","ENV432H1"]},{"type":"credits","amount":0.5,"courses":["EEB428H1","EEB440H1","ENV432H1"]}]},{"type":"program","text":"Immunology"}]}`,
				`  note: Immunology (3.0 Credits) - BIO130H1 (70%), IMM250H1, IMM340H1, IMM350H1, IMM360H1, IMM429H1/ IMM430H1/ IMM431H1/ IMM435H1`,
				`4 limit p3 {"type":"credits","courses":["PSY324H1","PSY326H1","PSY421H1","PSY424H1","PSY425H1","PSY426H1","PSY427H1","PSY405H1","PSY406H1","PSY405Y1","PSY406Y1"],"max_amount":1}`,
				`note: plus a disciplinary focus requiring 2.0-3.5 credits`,
			},
			nil},
		{"a focus's requirement under its heading, and wordings the item grammar writes otherwise; advice stays a note (ASSPE2270, shortened)",
			"(1.0 credit plus a disciplinary focus requiring 2.0-3.5 credits)\n1. STA130H1, STA238H1\n**Disciplinary Focuses**\nStudents in the Specialist Program in Statistical Science: Methods and Practice program must enrol in and complete at least one disciplinary focus.\nGlobal Health (ASFOC2270B): (3.0 credits) BIO120H1, BIO130H1, HMB203H1, HMB265H1/ BIO260H1, HMB323H1/ HMB303H1/ HMB306H1/ JAH350H1/ HMB342H1, HMB433H1/ HMB406H1/ HMB462H1/ HMB434H1/ HMB453H1 (Recommended: HMB433H1)\nSociology (ASFOC2270K): (2.5 credits) ( SOC100H1, SOC150H1) with a combined minimum grade average of 65%; SOC204H1; 1.0 credit from SOC270H1, SOC303H1, SOC312H1, SOC336H1, SOC363H1, SOC364H1.\nStudents interested in advanced study in Sociology should consider additional courses, in particular SOC201H1, SOC251H1, and SOC254H1\nEconomics (ASFOC2270N): (3.5 credits) ( ECO101H1, ECO102H1), ECO200Y1/ ECO206Y1, ECO202Y1/ ECO208Y1, 0.5 credit 300+ series ECO course with the exception of ECO374H1 and ECO375H1\nBiochemistry (ASFOC2270O): (3.0 credits)\nCHM135H1, CHM136H1, BCH210H1, BCH311H1, BCH370H1, BCH441H1",
			[]string{
				`1 allocation {"type":"credits","amount":1}`,
				`2 allocation p1 {"type":"and","items":[{"type":"course","code":"STA130H1"},{"type":"course","code":"STA238H1"}]}`,
				`3 allocation p1 {"type":"or","items":[{"type":"and","items":[{"type":"program","programs":["ASFOC2270B"],"text":"Global Health"},{"type":"course","code":"BIO120H1"},{"type":"course","code":"BIO130H1"},{"type":"course","code":"HMB203H1"},{"type":"or","items":[{"type":"course","code":"HMB265H1"},{"type":"course","code":"BIO260H1"}]},{"type":"or","items":[{"type":"course","code":"HMB323H1"},{"type":"course","code":"HMB303H1"},{"type":"course","code":"HMB306H1"},{"type":"course","code":"JAH350H1"},{"type":"course","code":"HMB342H1"}]},{"type":"or","items":[{"type":"course","code":"HMB433H1"},{"type":"course","code":"HMB406H1"},{"type":"course","code":"HMB462H1"},{"type":"course","code":"HMB434H1"},{"type":"course","code":"HMB453H1"}]}]},{"type":"and","items":[{"type":"program","programs":["ASFOC2270K"],"text":"Sociology"},{"type":"course","code":"SOC100H1"},{"type":"course","code":"SOC150H1"},{"type":"average","min_grade":65,"courses":["SOC100H1","SOC150H1"]},{"type":"course","code":"SOC204H1"},{"type":"credits","amount":1,"courses":["SOC270H1","SOC303H1","SOC312H1","SOC336H1","SOC363H1","SOC364H1"]}]},{"type":"and","items":[{"type":"program","programs":["ASFOC2270N"],"text":"Economics"},{"type":"course","code":"ECO101H1"},{"type":"course","code":"ECO102H1"},{"type":"or","items":[{"type":"course","code":"ECO200Y1"},{"type":"course","code":"ECO206Y1"}]},{"type":"or","items":[{"type":"course","code":"ECO202Y1"},{"type":"course","code":"ECO208Y1"}]},{"type":"credits","amount":0.5,"designators":["ECO"],"levels":[300,400],"exclude":["ECO374H1","ECO375H1"]}]},{"type":"and","items":[{"type":"program","programs":["ASFOC2270O"],"text":"Biochemistry"},{"type":"course","code":"CHM135H1"},{"type":"course","code":"CHM136H1"},{"type":"course","code":"BCH210H1"},{"type":"course","code":"BCH311H1"},{"type":"course","code":"BCH370H1"},{"type":"course","code":"BCH441H1"}]}]}`,
				`  note: Students interested in advanced study in Sociology should consider additional courses, in particular SOC201H1, SOC251H1, and SOC254H1`,
				`  note: Global Health (ASFOC2270B): Recommended: HMB433H1`,
				`note: plus a disciplinary focus requiring 2.0-3.5 credits`,
			},
			nil},
	})
}
